var station = global.get('station') || {type:'',data:null};
var data = station.data;
if(data != null){
    const firstFalseItem = data.selectedItems.find(item => item.done === false);
    if (firstFalseItem) {
      firstFalseItem.done = true;

      data.selectedItems.forEach(item => {
        if (item.poi === firstFalseItem.poi) {
          item.done = true;
        }
      });

      const nextFalseItem = data.selectedItems.find(item => item.done === false);
      if (nextFalseItem) {
        data.currentItem = { ...nextFalseItem, completed: false };
      } else {
        data.currentItem = { ...firstFalseItem, completed: true };
      }

        station.data = data;
        global.set('station', station)
        msg.payload = data;
        msg.type = 'next';
        msg.data = data;
        return msg;
    }

}

