    return null;
}

// แสดงสถานะกำลังรอ
node.status({ fill: "yellow", shape: "dot", text: "waiting confirm..." });

const interval = setInterval(() => {
    const status = flow.get("isConfirm");

    if (status !== undefined) {

        if (status === "confirm") {

            node.status({ fill: "green", shape: "dot", text: "confirmed" });
            node.send([{ payload: "confirm" }, null]);

            clearInterval(interval);
            context.set("checker", null);
            flow.set("isConfirm", undefined);

            // setTimeout(() => {
            //     node.status({});
            // }, 2000);
        }

        else if (status === "cancel") {

            node.status({ fill: "red", shape: "dot", text: "cancelled" });
            node.send([null, { payload: "cancel" }]);

            clearInterval(interval);
            context.set("checker", null);
            flow.set("isConfirm", undefined);

            // setTimeout(() => {
            //     node.status({});
            // }, 2000);
        }
    }

}, 1000);

// เก็บ interval id ไว้กันซ้ำ
context.set("checker", interval);

// cleanup ตอน redeploy
node.on("close", function () {
