var wafer_data = global.get("waferTransport")
var i = 0
var text = ''
if (wafer_data.selectedItems.length > 0){
    while ( i < wafer_data.selectedItems.length){
        wafer_name = wafer_data.selectedItems[i].name
        text += wafer_name.replace("/","-") + ','
        i++
    }
}
else{
    text = 'Charger,'
}
msg.url = `http://172.30.39.7:8001/wafer/${text}`
return msg
